//! ArkCompiler dynamic (ECMAScript) instruction set: opcode table, operand
//! layout and decoding.
//!
//! The table in `table.rs` is generated by `gen/gen_isa.py` from the official
//! `isa/isa.yaml` and checked in. An instruction is one opcode byte, or one of
//! four prefix bytes ([`Prefix`]) followed by a sub-opcode byte, then a fixed
//! operand layout: the length depends on the opcode alone, so code is walked
//! linearly with two table loads per instruction. Opcodes were never
//! renumbered, so the one table decodes files of every bytecode version.
//!
//! Nothing here panics on malformed code: [`Instruction::decode`] and
//! [`walk`] report undefined opcodes and truncated instructions as
//! [`DecodeError`].

mod decode;
mod table;
mod walk;

pub use decode::{DecodeError, Instruction, Operands, RegRange, Value};
pub use walk::{Walk, walk};

/// Prefix byte of a two-byte opcode.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Prefix {
    /// `callruntime.*`, `0xfb`.
    CallRuntime,
    /// `deprecated.*`, `0xfc`: encodings of old bytecode versions.
    Deprecated,
    /// `wide.*`, `0xfd`: variants with wider operands.
    Wide,
    /// `throw.*`, `0xfe`.
    Throw,
}

impl Prefix {
    pub const ALL: [Self; 4] = [Self::CallRuntime, Self::Deprecated, Self::Wide, Self::Throw];

    /// The prefix byte.
    #[inline]
    pub const fn byte(self) -> u8 {
        match self {
            Self::CallRuntime => 0xfb,
            Self::Deprecated => 0xfc,
            Self::Wide => 0xfd,
            Self::Throw => 0xfe,
        }
    }

    #[inline]
    pub const fn from_byte(byte: u8) -> Option<Self> {
        match byte {
            0xfb => Some(Self::CallRuntime),
            0xfc => Some(Self::Deprecated),
            0xfd => Some(Self::Wide),
            0xfe => Some(Self::Throw),
            _ => None,
        }
    }

    fn table(self) -> &'static [Option<Opcode>] {
        match self {
            Self::CallRuntime => &table::CALLRUNTIME_OPS,
            Self::Deprecated => &table::DEPRECATED_OPS,
            Self::Wide => &table::WIDE_OPS,
            Self::Throw => &table::THROW_OPS,
        }
    }
}

/// What an operand field holds.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum OperandKind {
    /// Register that is read.
    RegIn,
    /// Register that is written.
    RegOut,
    /// Zero-extended immediate.
    ImmUnsigned,
    /// Sign-extended immediate.
    ImmSigned,
    /// IEEE-754 double (`fldai`).
    ImmFloat,
    /// Signed branch offset in bytes, relative to the start of the instruction.
    JumpOffset,
    /// Inline-cache slot number: runtime bookkeeping, not program data.
    IcSlot,
    /// Index into the string / method / literal-array index of the method's region.
    /// The 32-bit ids of some `deprecated.*` opcodes are file offsets instead.
    StringId,
    MethodId,
    LiteralArrayId,
}

/// One operand field of an opcode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Operand {
    pub kind: OperandKind,
    /// Bit offset from the start of the instruction (opcode bytes included);
    /// fields are little-endian, least significant bit first.
    pub offset: u8,
    /// Width in bits: 4, 8, 16, 32 or 64.
    pub width: u8,
}

/// Bits of [`Opcode::flags`]; names follow the `isa.yaml` properties.
pub(crate) mod flag {
    pub const ACC_READ: u16 = 1 << 0;
    pub const ACC_WRITE: u16 = 1 << 1;
    pub const JUMP: u16 = 1 << 2;
    pub const CONDITIONAL: u16 = 1 << 3;
    pub const RETURN: u16 = 1 << 4;
    pub const THROW: u16 = 1 << 5;
    pub const THROW_IF: u16 = 1 << 6;
    pub const CALL: u16 = 1 << 7;
    pub const RANGE_0: u16 = 1 << 8;
    pub const RANGE_1: u16 = 1 << 9;
    pub const IC_SLOT: u16 = 1 << 10;
    pub const IC_TWO_SLOTS: u16 = 1 << 11;
}

/// One row of the opcode table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Opcode {
    pub prefix: Option<Prefix>,
    /// The opcode byte, or the sub-opcode byte when `prefix` is set.
    pub value: u8,
    /// Mnemonic as in `isa.yaml`, prefix included (`wide.callrange`). Several
    /// opcodes share a mnemonic when they differ only in operand widths.
    pub name: &'static str,
    /// Total length in bytes, opcode bytes included.
    pub len: u8,
    /// Operands in assembly (signature) order, which is not always encoding order.
    pub operands: &'static [Operand],
    flags: u16,
}

impl Opcode {
    /// Length in bytes.
    #[inline]
    pub const fn byte_len(&self) -> usize {
        self.len as usize
    }

    /// Number of opcode bytes before the operands: 2 when prefixed, else 1.
    #[inline]
    pub const fn opcode_len(&self) -> usize {
        if self.prefix.is_some() { 2 } else { 1 }
    }

    #[inline]
    const fn has(&self, bits: u16) -> bool {
        self.flags & bits != 0
    }

    /// Whether the accumulator is an input.
    #[inline]
    pub const fn reads_acc(&self) -> bool {
        self.has(flag::ACC_READ)
    }

    /// Whether the accumulator is an output.
    #[inline]
    pub const fn writes_acc(&self) -> bool {
        self.has(flag::ACC_WRITE)
    }

    /// Whether this is a branch (`jmp`, `jeqz`, ...); see [`Instruction::jump_target`].
    #[inline]
    pub const fn is_jump(&self) -> bool {
        self.has(flag::JUMP)
    }

    /// Whether this is a branch that may fall through.
    #[inline]
    pub const fn is_conditional_jump(&self) -> bool {
        self.has(flag::CONDITIONAL)
    }

    #[inline]
    pub const fn is_return(&self) -> bool {
        self.has(flag::RETURN)
    }

    /// Whether the instruction always throws (`throw`, `throw.notexists`, ...).
    #[inline]
    pub const fn is_throw(&self) -> bool {
        self.has(flag::THROW)
    }

    /// Whether this is a `throw.*` check that throws only when its condition holds.
    #[inline]
    pub const fn is_conditional_throw(&self) -> bool {
        self.has(flag::THROW_IF)
    }

    /// Whether control never reaches the next instruction: unconditional
    /// jump, return or unconditional throw.
    #[inline]
    pub const fn is_terminator(&self) -> bool {
        self.has(flag::RETURN | flag::THROW) || (self.is_jump() && !self.is_conditional_jump())
    }

    /// Whether the instruction calls a function or constructor: the `call*`,
    /// `supercall*`, `apply` and `newobj*` families. The callee is in the
    /// accumulator or a register, never an operand.
    #[inline]
    pub const fn is_call(&self) -> bool {
        self.has(flag::CALL)
    }

    /// Whether the instruction reads a run of consecutive registers; see
    /// [`Instruction::reg_range`].
    #[inline]
    pub const fn has_reg_range(&self) -> bool {
        self.has(flag::RANGE_0 | flag::RANGE_1)
    }

    /// Number of inline-cache slots the instruction occupies (0, 1 or 2),
    /// starting at its [`OperandKind::IcSlot`] operand.
    #[inline]
    pub const fn ic_slots(&self) -> u8 {
        if !self.has(flag::IC_SLOT) {
            0
        } else if self.has(flag::IC_TWO_SLOTS) {
            2
        } else {
            1
        }
    }

    /// The first operand of `kind`, if any.
    pub fn operand_of(&self, kind: OperandKind) -> Option<&'static Operand> {
        self.operands.iter().find(|operand| operand.kind == kind)
    }
}

/// Look up an unprefixed opcode. `None` for undefined bytes and for the
/// prefix bytes themselves.
#[inline]
pub fn opcode(byte: u8) -> Option<&'static Opcode> {
    table::PRIMARY_OPS[usize::from(byte)].as_ref()
}

/// Look up the opcode `sub` of a prefix.
#[inline]
pub fn prefixed_opcode(prefix: Prefix, sub: u8) -> Option<&'static Opcode> {
    prefix.table().get(usize::from(sub))?.as_ref()
}

/// Every defined opcode: unprefixed ones first, then each prefix in byte order.
pub fn opcodes() -> impl Iterator<Item = &'static Opcode> {
    let prefixed = Prefix::ALL.into_iter().flat_map(|prefix| prefix.table());
    table::PRIMARY_OPS.iter().chain(prefixed).filter_map(Option::as_ref)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn table_matches_isa_information() {
        // `isa_information` in isa.yaml 26.0.1.0: last_opcode_idx 0xe1, throw 0x09,
        // wide 0x14, deprecated 0x2e, callruntime 0x1b.
        let last = |prefix: Prefix| opcodes().filter(|op| op.prefix == Some(prefix)).map(|op| op.value).max();
        assert_eq!(opcodes().filter(|op| op.prefix.is_none()).map(|op| op.value).max(), Some(0xe1));
        assert_eq!(last(Prefix::Throw), Some(0x09));
        assert_eq!(last(Prefix::Wide), Some(0x14));
        assert_eq!(last(Prefix::Deprecated), Some(0x2e));
        assert_eq!(last(Prefix::CallRuntime), Some(0x1b));
        assert_eq!(opcodes().count(), 332);
        assert_eq!(opcodes().filter(|op| op.prefix.is_none()).count(), 226);

        for byte in 0xe2..=0xff {
            assert_eq!(opcode(byte), None, "{byte:#04x}");
        }
        assert_eq!(prefixed_opcode(Prefix::Throw, 0x0a), None);
        assert_eq!(prefixed_opcode(Prefix::Deprecated, 0xff), None);
        for prefix in Prefix::ALL {
            assert_eq!(Prefix::from_byte(prefix.byte()), Some(prefix));
        }
    }

    #[test]
    fn rows_sit_at_their_own_index() {
        let mut seen = HashSet::new();
        for op in opcodes() {
            assert!(seen.insert((op.prefix, op.value)), "{} listed twice", op.name);
            let found = match op.prefix {
                None => opcode(op.value),
                Some(prefix) => prefixed_opcode(prefix, op.value),
            };
            assert!(found.is_some_and(|found| std::ptr::eq(found, op)), "{}", op.name);
            // Mnemonics carry their prefix, except the bare `throw`.
            let family = op.prefix.map(|prefix| format!("{prefix:?}").to_lowercase());
            assert_eq!(
                op.name.split_once('.').map(|(head, _)| head).filter(|_| op.prefix.is_some()),
                family.as_deref().filter(|_| op.name != "throw"),
                "{}",
                op.name
            );
        }
    }

    #[test]
    fn length_is_opcode_bytes_plus_operand_widths() {
        for op in opcodes() {
            let bits: usize = op.operands.iter().map(|operand| usize::from(operand.width)).sum();
            assert_eq!(op.byte_len() * 8, op.opcode_len() * 8 + bits, "{}", op.name);

            // The fields tile the instruction: no gap, no overlap, whatever the signature order.
            let mut fields: Vec<_> = op.operands.iter().map(|o| (usize::from(o.offset), usize::from(o.width))).collect();
            fields.sort_unstable();
            let end = fields.iter().fold(op.opcode_len() * 8, |at, &(offset, width)| {
                assert_eq!(offset, at, "{}", op.name);
                at + width
            });
            assert_eq!(end, op.byte_len() * 8, "{}", op.name);
        }
    }

    #[test]
    fn operand_widths_fit_their_value_types() {
        for op in opcodes() {
            for operand in op.operands {
                let max = match operand.kind {
                    OperandKind::RegIn | OperandKind::RegOut | OperandKind::IcSlot => 16,
                    OperandKind::ImmUnsigned | OperandKind::JumpOffset => 32,
                    OperandKind::StringId | OperandKind::MethodId | OperandKind::LiteralArrayId => 32,
                    OperandKind::ImmSigned | OperandKind::ImmFloat => 64,
                };
                assert!(matches!(operand.width, 4 | 8 | 16 | 32 | 64) && operand.width <= max, "{}", op.name);
                assert!(operand.kind != OperandKind::ImmFloat || operand.width == 64, "{}", op.name);
            }
        }
    }

    #[test]
    fn flags_agree_with_operands() {
        for op in opcodes() {
            let count = |kind| op.operands.iter().filter(|operand| operand.kind == kind).count();
            assert_eq!(count(OperandKind::JumpOffset), usize::from(op.is_jump()), "{}", op.name);
            assert_eq!(count(OperandKind::IcSlot), usize::from(op.ic_slots() > 0), "{}", op.name);
            assert!(!op.is_conditional_jump() || op.is_jump(), "{}", op.name);
            assert!(!(op.is_throw() && op.is_conditional_throw()), "{}", op.name);
            assert_eq!(op.is_throw() || op.is_conditional_throw(), op.prefix == Some(Prefix::Throw), "{}", op.name);
            for id in [OperandKind::StringId, OperandKind::MethodId, OperandKind::LiteralArrayId] {
                assert!(count(id) <= 1, "{}", op.name);
            }
            if op.has_reg_range() {
                assert!(count(OperandKind::RegIn) >= 1 && count(OperandKind::ImmUnsigned) >= 1, "{}", op.name);
            }
        }
    }

    #[test]
    fn spot_checks_against_isa_yaml() {
        let by_name = |name: &str| opcodes().filter(|op| op.name == name).collect::<Vec<_>>();

        let jmp = by_name("jmp");
        assert_eq!(jmp.iter().map(|op| (op.value, op.len)).collect::<Vec<_>>(), [(0x4d, 2), (0x4e, 3), (0x98, 5)]);
        assert!(jmp.iter().all(|op| op.is_terminator() && !op.is_conditional_jump() && !op.reads_acc()));

        let jeqz = opcode(0x4f).unwrap();
        assert!(jeqz.is_jump() && jeqz.is_conditional_jump() && !jeqz.is_terminator() && jeqz.reads_acc());

        let ret = opcode(0x64).unwrap();
        assert!(ret.name == "return" && ret.is_return() && ret.is_terminator() && ret.reads_acc() && !ret.writes_acc());
        assert!(opcode(0x65).unwrap().is_return() && !opcode(0x65).unwrap().reads_acc());

        let throw = prefixed_opcode(Prefix::Throw, 0x00).unwrap();
        assert!(throw.name == "throw" && throw.is_throw() && throw.is_terminator() && throw.len == 2);
        let if_hole = prefixed_opcode(Prefix::Throw, 0x09).unwrap();
        assert_eq!(if_hole.name, "throw.undefinedifholewithname");
        assert!(if_hole.is_conditional_throw() && !if_hole.is_terminator());
        assert!(if_hole.operand_of(OperandKind::StringId).is_some());

        let callthis1 = by_name("callthis1")[0];
        assert!(callthis1.is_call() && callthis1.ic_slots() == 2 && callthis1.reads_acc() && callthis1.writes_acc());
        assert!(by_name("newobjrange").iter().all(|op| op.is_call() && op.has_reg_range()));
        assert!(by_name("definefunc").iter().all(|op| !op.is_call() && op.operand_of(OperandKind::MethodId).is_some()));
        assert!(!by_name("ldobjbyname")[0].is_call());

        let lda_str = opcode(0x3e).unwrap();
        assert_eq!((lda_str.name, lda_str.len, lda_str.ic_slots()), ("lda.str", 3, 0));
        assert_eq!(lda_str.operands, [Operand { kind: OperandKind::StringId, offset: 8, width: 16 }]);

        // Signature order differs from encoding order: `definefunc imm1, method_id, imm2`.
        let kinds = |op: &Opcode| op.operands.iter().map(|operand| operand.kind).collect::<Vec<_>>();
        assert_eq!(kinds(opcode(0x33).unwrap()), [OperandKind::IcSlot, OperandKind::MethodId, OperandKind::ImmUnsigned]);
        assert_eq!(kinds(opcode(0x44).unwrap()), [OperandKind::RegOut, OperandKind::RegIn]);
    }
}
